    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    sep = next(v for v in range(1, 10) if any(all(x == v for x in row) for row in g))
    hr = [r for r, row in enumerate(g) if all(x == sep for x in row)]
    vc = [c for c in range(w) if all(g[r][c] == sep for r in range(h))]

    def intervals(n, cuts):
        out, a = [], 0
        for b in cuts + [n]:
            if a < b:
                out.append((a, b))
            a = b + 1
        return out

    bands = intervals(h, hr)
    panels = intervals(w, vc)
    original = [row[:] for row in g]

    def pattern(r0, r1, c0, c1, color):
        return {(r-r0, c-c0) for r in range(r0, r1) for c in range(c0, c1)
                if original[r][c] == color}

    for r0, r1 in bands:
        colors = {original[r][c] for r in range(r0, r1) for c in range(w)
                  if original[r][c] not in (0, sep)}
        for color in colors:
            occ = []
            for i, (c0, c1) in enumerate(panels):
                pts = pattern(r0, r1, c0, c1, color)
                if pts:
                    occ.append((i, pts))

            # If a lone pattern has a neighboring panel of the same dimensions,
            # make its reflected counterpart there (prefer the panel to the right).
            if len(occ) == 1:
                i, pts = occ[0]
                c0, c1 = panels[i]
                candidates = [j for j in (i+1, i-1) if 0 <= j < len(panels)
                              and panels[j][1]-panels[j][0] == c1-c0]
                if candidates:
                    j = candidates[0]
                    d0, d1 = panels[j]
                    for rr, cc in pts:
                        g[r0+rr][d1-1-cc] = color

            # When two adjacent panels carry near-matching versions of the same
            # motif, align the right-hand one to the horizontal reflection of left.
            for (i, left), (j, right) in zip(occ, occ[1:]):
                if j != i+1:
                    continue
                c0, c1 = panels[i]
                d0, d1 = panels[j]
                if c1-c0 != d1-d0 or len(left) == 0:
                    continue
                reflected = {(rr, (c1-c0-1)-cc) for rr, cc in left}
                union = reflected | right
                similarity = len(reflected & right) / len(union) if union else 1.0
                if similarity >= 0.45:
                    # Clear only this color from the target panel, then write mirror.
                    for r in range(r0, r1):
                        for c in range(d0, d1):
                            if g[r][c] == color:
                                g[r][c] = 0
                    for rr, cc in reflected:
                        g[r0+rr][d0+cc] = color
