    def spans(n, cuts):
        out, a = [], 0
        for b in cuts + [n]:
            if a < b:
                out.append((a, b))
            a = b + 1
        return out

    bands, panels = spans(h, hc), spans(w, vc)
    src = [row[:] for row in g]
    active_pairs = set()

    # A pair of side-by-side rooms is a mirrored pair when some band shows
    # the same colored motif mirrored across their shared wall.
    for color in range(1, 10):
        if color == sep:
            continue
        for bi, (r0, r1) in enumerate(bands):
            for pi in range(len(panels)-1):
                a0, a1 = panels[pi]
                b0, b1 = panels[pi+1]
                if a1-a0 != b1-b0:
                    continue
                left = {(r-r0, c-a0) for r in range(r0,r1) for c in range(a0,a1)
                        if src[r][c] == color}
                right = {(r-r0, c-b0) for r in range(r0,r1) for c in range(b0,b1)
                         if src[r][c] == color}
                mirrored = {(rr, a1-a0-1-cc) for rr,cc in left}
                if left and right and mirrored == right:
                    active_pairs.add((color, pi))

    for color, pi in active_pairs:
        a0, a1 = panels[pi]
        b0, b1 = panels[pi+1]
        width = a1-a0

        # First complete horizontal counterparts in bands where there is
        # evidence of this motif on at least one side.
        for r0, r1 in bands:
            left = [(r,c) for r in range(r0,r1) for c in range(a0,a1) if src[r][c] == color]
            right = [(r,c) for r in range(r0,r1) for c in range(b0,b1) if src[r][c] == color]
            if left and not right:
                for r,c in left:
                    g[r][b1-1-(c-a0)] = color
            elif right and not left:
                for r,c in right:
                    g[r][a1-1-(c-b0)] = color

        # Reflect a motif over a horizontal separator only when the adjacent
        # band already contains the same color in this pair of rooms.
        for bi in range(len(bands)-1):
            (u0,u1), (d0,d1) = bands[bi], bands[bi+1]
            upper = [(r,c) for r in range(u0,u1) for c in range(a0,b1) if src[r][c] == color]
            lower = [(r,c) for r in range(d0,d1) for c in range(a0,b1) if src[r][c] == color]
