                        g[rr][c] = color
                for r,c in lower:
                    rr = 2*wall-r
                    if u0 <= rr < u1 and g[rr][c] == 0:
                        g[rr][c] = color

        # Once vertically copied, complete any missing horizontal counterpart.
        for r0, r1 in bands:
            left = [(r,c) for r in range(r0,r1) for c in range(a0,a1) if g[r][c] == color]
